online_css:
/* Online Rx section (/online/). Loaded after the site's page stylesheet; reuses its tokens
   (--gold, --gold-hi, --muted, --line, --line2, --card, --surface, --radius, --shadow). */

.reviewed{font-size:12.5px;letter-spacing:.06em;color:var(--dim);margin-top:14px}
.reviewed b{color:var(--muted);font-weight:400}
.answer{font-size:18px;color:var(--text);max-width:760px;margin:22px 0 30px;line-height:1.65}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;align-items:center}
.section-answer{font-size:17px;color:var(--text);max-width:760px;margin:-28px 0 40px}
.sec-head + .section-answer{margin-top:-30px}
section.tight{padding:72px 0}

/* Three-step strip */
.steps3{display:grid;gap:22px;counter-reset:s}
@media(min-width:760px){.steps3{grid-template-columns:repeat(3,1fr)}}

/* Program cards */
.program-card{display:flex;flex-direction:column}
.program-card .actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:auto;padding-top:22px}
.program-card .actions .btn{padding:12px 22px;font-size:12px}

/* State cards */
.state-card .tag{display:inline-block;margin-top:12px;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-hi);border:1px solid var(--line);border-radius:999px;padding:5px 12px}

/* Placeholder marker: anything still in [BRACKETS] */
.ph{background:#fff4d6;outline:1px dashed #c9a24e;border-radius:4px;padding:0 4px;color:#7c5e26;font-weight:400}

/* Product facts box */
.facts{background:var(--card);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow);overflow:hidden}
.facts h2{font-size:28px;padding:26px 30px 18px;border-bottom:1px solid var(--line2)}
.facts dl{display:grid;margin:0}
.facts dl > div{display:grid;gap:6px;padding:18px 30px;border-bottom:1px solid var(--line2)}
@media(min-width:760px){.facts dl > div{grid-template-columns:220px 1fr;gap:24px}}
.facts dt{font-size:11.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold-hi);font-weight:400;padding-top:3px}
.facts dd{margin:0;color:var(--text);font-size:15.5px}
.facts dd ul{margin:0;padding-left:18px}
.facts dd li{margin:4px 0}
.facts .boxed{background:#fbf3e3}
.facts .boxed dt{color:#8a4b12}
.facts .pi{padding:18px 30px;font-size:14px}
.facts .pi a{color:var(--gold-hi);text-decoration:underline;text-underline-offset:3px}

/* Tables */
.table-wrap{overflow-x:auto;border:1px solid var(--line2);border-radius:14px;background:var(--card);box-shadow:var(--shadow)}
.rx-table{width:100%;border-collapse:collapse;font-size:15px}
.rx-table.wide{min-width:640px}
@media(max-width:759px){.facts h2{padding:22px 20px 14px}.facts dl > div{padding:16px 20px}.facts .pi{padding:16px 20px}.rx-table th,.rx-table td{padding:12px 14px}}
.rx-table th,.rx-table td{text-align:left;padding:14px 18px;border-bottom:1px solid var(--line2);vertical-align:top}
.rx-table th{font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-hi);font-weight:400;background:var(--surface)}
.rx-table tr:last-child td{border-bottom:0}
.rx-table a{color:var(--gold-hi);text-decoration:underline;text-underline-offset:3px}

/* Prose blocks */
.prose{max-width:780px}
.prose h2{font-size:clamp(30px,4vw,44px);margin:14px 0 16px}
.prose h3{font-size:24px;margin:26px 0 8px}
.prose p{color:var(--muted);margin-bottom:14px}
.prose ul{color:var(--muted);padding-left:20px;margin-bottom:14px}
.prose li{margin:6px 0}
.prose a{color:var(--gold-hi);text-decoration:underline;text-underline-offset:3px}

/* FAQ */
.faq{max-width:860px;display:grid;gap:12px}
.faq details{background:var(--card);border:1px solid var(--line2);border-radius:14px;padding:20px 24px;box-shadow:var(--shadow)}
.faq summary{cursor:pointer;font-family:'Cormorant Garamond',serif;font-size:22px;list-style:none;display:flex;justify-content:space-between;gap:16px}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"+";color:var(--gold);font-family:'Jost',sans-serif;font-size:22px;line-height:1}
.faq details[open] summary::after{content:"\2212"}
.faq details p{color:var(--muted);margin-top:12px}
.faq details a{color:var(--gold-hi);text-decoration:underline}

/* Compliance block (above the footer on every /online/ page) */
.online-compliance{background:var(--surface);border-top:1px solid var(--line);padding:56px 0}
.online-compliance .oc-grid{display:grid;gap:28px;align-items:start}
@media(min-width:860px){.online-compliance .oc-grid{grid-template-columns:150px 1fr}}
.online-compliance .cert-badge{display:inline-flex;flex-direction:column;align-items:center;gap:8px;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-hi);text-align:center}
.online-compliance .cert-badge img{width:100px;height:100px}
.online-compliance h2{font-size:26px;margin-bottom:12px}
.online-compliance ul{list-style:none;display:grid;gap:9px;color:var(--muted);font-size:14.5px}
.online-compliance li{padding-left:18px;position:relative}
.online-compliance li::before{content:"";position:absolute;left:0;top:.72em;width:7px;height:1px;background:var(--gold)}
.online-compliance li b{color:var(--text);font-weight:400}
.online-compliance .emergency{color:#8a2b12}
.online-compliance .oc-links{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:18px;font-size:12px;letter-spacing:.14em;text-transform:uppercase}
.online-compliance .oc-links a{color:var(--gold-hi)}

/* Start page */
.start{padding:72px 0 96px}
.start h1{font-size:clamp(40px,6vw,64px)}
.start .lead{margin:16px 0 34px}
.choice-grid{display:grid;gap:16px;max-width:760px}
@media(min-width:620px){.choice-grid{grid-template-columns:1fr 1fr}}
.choice{display:flex;flex-direction:column;align-items:flex-start;gap:6px;width:100%;text-align:left;cursor:pointer;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:24px 26px;box-shadow:var(--shadow);font:inherit;color:var(--text);transition:.25s}
.choice:hover,.choice:focus-visible{border-color:var(--gold);transform:translateY(-2px);outline:none}
.choice[aria-pressed="true"]{border-color:var(--gold);background:#fbf6ea}
.choice strong{font-family:'Cormorant Garamond',serif;font-size:28px;font-weight:500;line-height:1.1}
.choice span{font-size:13px;color:var(--muted)}
.route{max-width:760px;margin-top:28px;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:28px 30px;box-shadow:var(--shadow)}
.route[hidden],.start [hidden]{display:none!important}
.route h2{font-size:30px;margin-bottom:10px}
.route p{color:var(--muted);margin-bottom:18px}
.route .btn[aria-disabled="true"]{opacity:.55;pointer-events:none}
.route .pending{font-size:13px;color:#7c5e26;margin-top:10px}
.waitlist{display:grid;gap:14px;max-width:520px}
.waitlist label{display:grid;gap:6px;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-hi)}
.waitlist input,.waitlist select{font:inherit;font-size:16px;padding:13px 14px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--text);letter-spacing:0;text-transform:none}
.waitlist .hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.waitlist .note{font-size:13px;color:var(--muted);letter-spacing:0;text-transform:none}
.waitlist .msg{font-size:14px;color:var(--gold-deep)}
.already{margin-top:44px;padding-top:22px;border-top:1px solid var(--line2);max-width:760px;color:var(--muted);font-size:15px}
.already a{color:var(--gold-hi);text-decoration:underline;text-underline-offset:3px}
.back-link{display:inline-block;margin-top:18px;font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-hi);background:none;border:0;cursor:pointer}

/* Neutral hero (Vyleesi): clinic reception lounge instead of the default lifestyle photo */
.phero.phero-neutral{background-image:linear-gradient(90deg,rgba(250,248,243,.99) 0%,rgba(250,248,243,.96) 49%,rgba(250,248,243,.56) 70%,rgba(250,248,243,.12) 100%),url('/wp-content/uploads/ia-media/images/facility/reception-lounge.webp');background-size:auto 100%;background-position:right center;background-repeat:no-repeat}
@media(max-width:820px){.phero.phero-neutral{background-image:linear-gradient(90deg,rgba(250,248,243,.99) 0%,rgba(250,248,243,.94) 72%,rgba(250,248,243,.6) 100%),url('/wp-content/uploads/ia-media/images/facility/reception-lounge.webp');background-position:76% center}}

/* Current patients box (refill check-in + patient portal) */
.current-patients{display:flex;flex-wrap:wrap;gap:18px 28px;align-items:center;justify-content:space-between;margin-top:30px;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:24px 28px;box-shadow:var(--shadow)}
.current-patients h3{font-size:24px;margin-bottom:4px}
.current-patients p{color:var(--muted);font-size:15px;margin:0}
.current-patients .btn{padding:12px 24px;font-size:12px}
.online-compliance li a{color:var(--gold-hi);text-decoration:underline;text-underline-offset:3px}
.start .terms{font-size:13px;color:var(--muted);margin-top:12px;max-width:560px}
.updated{font-size:13px;color:var(--muted);margin:10px 0 0}

/* Peptide store (Nov 18, 2026) */
.shop-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:22px}
.prod-card{background:#fff;border:1px solid rgba(168,122,34,.22);border-radius:18px;padding:26px 24px;display:flex;flex-direction:column;gap:10px;box-shadow:0 10px 30px rgba(40,30,10,.05)}
.prod-card .tag{align-self:flex-start;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#a87a22;border:1px solid rgba(168,122,34,.35);border-radius:999px;padding:4px 10px}
.prod-card h3{margin:4px 0 0;font-size:24px}
.prod-card h3 a{color:inherit;text-decoration:none}
.prod-card .prod-short{color:var(--muted,#6b6257);font-size:14.5px;margin:0}
.prod-card .cta-row{margin-top:auto;display:flex;gap:10px;flex-wrap:wrap}
.prod-card .cta-row .btn{padding:12px 18px;font-size:11.5px}
.prod-price{margin:6px 0 0;font-size:15px;color:var(--muted,#6b6257)}
.prod-price b{font-family:"Cormorant Garamond",serif;font-size:34px;font-weight:500;color:var(--text,#1f1a14);margin-right:4px}
.prod-price.big b{font-size:44px}
.refund-note{margin-top:26px;padding:18px 22px;border-left:3px solid #a87a22;background:#fbf3e3;border-radius:10px;font-size:15px}
